    def test_a_member_read_the_instance_is_assigned_is_what_a_call_reaches(
        self, tmp_path
    ):
        """A field the instance is assigned a member read, `this.cb =
        this.helper`, holds that member, whether the class declares the
        field or not."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                class C {
                  cb: () => void;
                  helper() {}
                  constructor() { this.cb = this.helper; }
                  run() { this.cb(); }
                }
                class D {
                  helper() {}
                  setup() { this.z = this.helper; }
                  run() { this.z(); }
                }
                """,
            },
        )
        assert _calls(builder, "FILE:a.ts::C::run") == ["FILE:a.ts::C::helper"]
        assert _calls(builder, "FILE:a.ts::D::run") == ["FILE:a.ts::D::helper"]

    def test_a_field_the_instance_is_assigned_hides_the_classs_method(self, tmp_path):
        """A field a method assigns to the instance, `this.name = ...`, is
        found before a method of the name, the class's or a base's: a call
        of it reaches the member it is assigned, bound or not, else stays
        open with the method as a candidate."""
        builder = _index(
            tmp_path,
            {
                "a.js": """
                function make() { return () => 1; }
                class B { f(x) {} g() {} }
                class D extends B {
                  constructor() {
                    super();
                    this.f = this.f.bind(this);
                    this.g = make();
                    this.h = this.k.bind(this);
                  }
                  k() {}
                  h() {}
                  run() { this.f(1); this.g(); this.h(); }
                }
                """,
            },
        )
        assert _candidates(builder, "FILE:a.js::D::run") == {
            "FILE:a.js::B::f": None,
            "REF:this.g": ["FILE:a.js::B::g"],
            "FILE:a.js::D::k": None,
        }

    def test_this_call_resolves_through_a_generic_base_class(self, tmp_path):
        """`class A<T extends B> extends C<T>` inherits from C, not B."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                class Decoy {
                  prepare() {}
                }

                class Base<T> {
                  prepare() {}
                }

                class Child<T extends Decoy> extends Base<T> {
                  run() {
                    this.prepare();
                  }
                }
                """
            },
        )
        assert _calls(builder, "FILE:a.ts::Child::run") == ["FILE:a.ts::Base::prepare"]

    def test_call_through_a_dependency_import_is_external(self, tmp_path):
        """A name imported from a declared dependency does not reach a
        project definition of that name; one imported from a project
        package does."""
