    def test_global_is_the_librarys_unless_its_file_binds_the_name(self, tmp_path):
        """`document` and `globalThis.console` are the browser's and the
        language's; a parameter called `document` is not, and no method
        it names is pinned to a project definition. A method called
        `catch` takes no parameter, a comment or JSX text declares no name,
        what follows a `/* */` comment is read, and a `<` that goes on with
        a comparison from the line before opens no element, as one where a
        statement or a value starts does."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                export class Page {
                    typeset() {}
                    log() {}
                    querySelector() {}
                }

                export function setup() {}

                export function draw() {
                    document.querySelector("p").remove();
                    globalThis.console.log("drawn");
                    globalThis.setup();
                    const tip = /* shown */"it's"; setup();
                }
                """,
                "b.ts": """
                export function print(document) {
                    document.typeset();
                    document.querySelector("p");
                }
                """,
                "c.ts": """
                // The page reported on, unless let pages be shown.
                let page;
                export function report(done) {
                    done.catch(document.close);
                    document.querySelector("p");
                }
                """,
                "d.tsx": """
                import { setup } from "./a";
                export function Help() {
                    return <p>Pick a type document, or a `</p>;
                }
                export function show(a, b) {
                    document.querySelector("p");
                    const fits = a
                        <b && b > 0;
                    setup();
                }
                export function Note(c) {
                    if (c)
                        <p>setup()</p>;
                    const shown = /setup()/g
                    <p>setup()</p>;
                    outer: for (;;) {
                        break outer
                        <p>setup()</p>;
                        continue\vouter
                        <p>setup()</p>;
                        break\ufeffouter
                        /setup()/g.test("");
                    }
                    return [...
                        <p>setup()</p>];
                }
                """,
            },
        )
        assert _calls(builder, "FILE:a.ts::draw") == ["FILE:a.ts::setup"] * 2
        assert _calls(builder, "FILE:c.ts::report") == []
        assert _calls(builder, "FILE:d.tsx::show") == ["FILE:a.ts::setup"]
        assert _calls(builder, "FILE:d.tsx::Note") == []
        assert "page" in builder.js_bound["FILE:c.ts"]
        assert "pages" not in builder.js_bound["FILE:c.ts"]
        assert _calls(builder, "FILE:b.ts::print") == [
            "REF:document.querySelector",
            "REF:document.typeset",
        ]
        edges = {
            e["target"]: e
            for e in builder.edges
            if e["source"] == "FILE:b.ts::print" and e["relation"] == "CALLS"
        }
        assert edges["REF:document.typeset"]["metadata"]["candidates"] == [
            "FILE:a.ts::Page::typeset"
        ]

    def test_function_passed_to_a_standard_method_is_typed_by_it(self, tmp_path):
        """What `map`, `forEach`, `find`, `reduce` and `then` hand to the
        function they are passed types its parameters, and what `map`
        returns is typed by what that function returns."""
        builder = _index(
            tmp_path,
            {
                "a.ts": """
                export class Schema {
                    child(): Child {
                        return new Child();
                    }
                }

                export class Child {
                    run() {}
                }

                export class Decoy {
                    child() {}
                    run() {}
                }

                export function each(all: Schema[], later: Promise<Schema>) {
                    all.forEach((schema) => schema.child());
                    all.find((schema) => schema.child()).child();
                    all.reduce((total, schema) => total + schema.child(), 0);
                    later.then((schema) => schema.child());
                }

                export function mapped(all: Array<Schema>) {
                    all.map((schema) => schema.child()).forEach((child) => {
                        child.run();
                    });
                }
                """
            },
        )
        child = "FILE:a.ts::Schema::child"
        assert _calls(builder, "FILE:a.ts::each") == [child] * 5
        assert _calls(builder, "FILE:a.ts::mapped") == [child]
        assert _calls(builder, "FILE:a.ts::mapped::callback@25") == [
            "FILE:a.ts::Child::run"
        ]

