        builder = _index(
            tmp_path,
            {
                "a.ts": """
                class A { use() {} }
                class B { use() {} }
                export function farcase(k: number) {
                  let x = new A();
                  switch (k) {
                    case          (x = new B(), 2): x.use();
                  }
                  x.use();
                }
                """,
            },
        )
        assert _calls(builder, "FILE:a.ts::farcase") == [
            "FILE:a.ts::A",
            "FILE:a.ts::B",
            "FILE:a.ts::B::use",
            "FILE:a.ts::B::use",
        ]

