    def test_cpp_declarations_bases_and_lambdas(self, tmp_path):
        """A spaced `ns ::T` parameter is `ns::T`; a base under a namespace a
        macro also opens elsewhere is found by its written qualifier; a
        lambda with a return type binds its parameters; `typename
        std::...` declares no type parameter `std`, and a macro before
        `::std::string` is no type."""
        builder = _index(
            tmp_path,
            {
                "a.cc": """
                #include <string>
                #define GTEST_API_
                #define OPEN namespace internal {
                namespace ns1 { class Uq { public: void q() {} }; }
                namespace testing { namespace internal {
                class Helper { protected: void Record() {} };
                template <typename T, typename std::enable_if<true>::type = 0>
                void Gen(T t) {}
                GTEST_API_ ::std::string Where() { return ""; }
                class Path { public: const char* c_str() const { return 0; } };
                } }
                struct Dog { void bark() {} };
                class RecordTest : public testing::internal::Helper {
                 public:
                  void Run() { Record(); }
                };
                void run2(ns1 ::Uq u) { u.q(); }
                void run3() {
                  auto f = [](Dog d) -> int { d.bark(); return 0; };
                  testing::internal::Where().c_str();
                }
                """
            },
        )
        assert _calls(builder, "FILE:a.cc::RecordTest::Run") == [
            "FILE:a.cc::testing::internal::Helper::Record"
        ]
        assert _calls(builder, "FILE:a.cc::run2") == ["FILE:a.cc::ns1::Uq::q"]
        assert _calls(builder, "FILE:a.cc::run3") == [
            "FILE:a.cc::Dog::bark",
            "FILE:a.cc::testing::internal::Where",
        ]

    def test_cpp_written_qualifiers_and_spaced_names(self, tmp_path):
        """A written qualifier names a namespace from the call's scope or one
        around it, not any of its last name: `testing::internal::f()` is not
        `other::internal::f`, where a macro opens `internal`. An all-caps
        name before `::` in a return type is a namespace, and a base list
        reads `ns ::Base` as `ns::Base`."""
        builder = _index(
            tmp_path,
            {
                "a.h": """
                namespace other { namespace internal {
                class Test { public: void f() {} };
                void work() {}
                } }
                """,
                "b.h": """
                #define OPEN_I namespace internal {
                #define CLOSE_I }
                namespace testing {
                OPEN_I
                class Test { public: void f() {} };
                void work() {}
                CLOSE_I
                }
                """,
                "c.cc": """
                #include "a.h"
                #include "b.h"
                namespace NS { class T2 { public: void good() {} }; }
                class T2 { public: void bad() {} };
                namespace ns1 { class Base { public: void b() {} }; }
                NS ::T2 mk() { return {}; }
                class C : public ns1 ::Base { public: void run() { b(); } };
                void g() {
                  testing::internal::Test t;
                  t.f();
                  testing::internal::work();
                  mk().good();
                  mk().bad();
                }
                """,
            },
        )
        assert _calls(builder, "FILE:c.cc::g") == [
            "FILE:b.h::testing::Test::f",
            "FILE:b.h::testing::work",
            "FILE:c.cc::NS::T2::good",
            "FILE:c.cc::mk",
            "FILE:c.cc::mk",
            "REF:bad",
        ]
        assert _calls(builder, "FILE:c.cc::C::run") == ["FILE:c.cc::ns1::Base::b"]

